export function getPost(slug: string): BlogPost | undefined {
  return posts.find((p) => p.slug === slug);
}

export function otherPosts(slug: string, limit = 3): BlogPost[] {
  return posts.filter((p) => p.slug !== slug).slice(0, limit);
}
